[URL Rewrite]
request if ${url} ~= /^https?:\/\/(syh|www)\.zybang\.com\/adx\//i then reject(200)

[Rule]
DOMAIN-SUFFIX, bu01.zybang.com,REJECT
DOMAIN-SUFFIX, bu02.zybang.com,REJECT

[MITM]
hostname = %APPEND% syh.zybang.com, www.zybang.com
